# owner: platform
"""Lay students out in rows of seats, by last name."""

from typing import Iterable, List

from rosterkit.models import Student


def _sort_key(student: Student):
    last = student.last_name.casefold()
    return (last, student.first_name.casefold())


def _check(students: List[Student], size: int) -> None:
    if size <= 0:
        raise ValueError(f"bad seat count: {size}")
    if not students:
        raise ValueError("no students to seat")


def _chunks(items: List[Student], size: int):
    return [
        items[start:start + size]
        for start in range(0, len(items), size)
    ]


def _row_line(number: int, group: List[Student]) -> str:
    names = " | ".join(s.display_name for s in group)
    return f"Row {number}: {names}"


# ---
def seating_rows(
    students: Iterable[Student], seats_per_row: int
) -> List[str]:
    """One line per row, students sorted by last name."""
    people = sorted(students, key=_sort_key)
    _check(people, seats_per_row)
    groups = _chunks(people, seats_per_row)
    numbered = enumerate(groups, 1)
    return [_row_line(n, g) for n, g in numbered]

