# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.seating import seating_rows


def make(last, first):
    return Student("x", last, first, "A")


class SeatingTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            make("Halloway", "Juno"),
            make("Quillon", "Ada"),
            make("Dunmere", "Piet")
        ]

    def test_sorted_and_split_into_rows(self):
        self.assertEqual(
            seating_rows(self.students, 2),
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Quillon, Ada"
            ]
        )

    def test_single_long_row(self):
        rows = seating_rows(self.students, 10)
        self.assertEqual(len(rows), 1)

    def test_sort_ignores_case(self):
        people = [make("zed", "A"), make("Abel", "B")]
        rows = seating_rows(people, 1)
        self.assertTrue(rows[0].startswith("Row 1: Abel"))

    def test_first_name_breaks_ties(self):
        people = [make("Lee", "Zoe"), make("Lee", "Al")]
        rows = seating_rows(people, 2)
        expected = "Row 1: Lee, Al | Lee, Zoe"
        self.assertEqual(rows, [expected])

    def test_zero_seats(self):
        with self.assertRaises(ValueError):
            seating_rows(self.students, 0)

    def test_negative_seats(self):
        with self.assertRaises(ValueError):
            seating_rows(self.students, -3)

    def test_no_students(self):
        with self.assertRaises(ValueError):
            seating_rows([], 2)
